//! Vanilla identities generated from source-attributed data at build time.
//!
//! [`Enchantment`] is the one enchantment type of the workspace (decision
//! 0052). Its variants, ids, names and rules are generated by
//! `build/enchantments.rs`; this module adds the parse rules and the
//! per-stack level table [`Enchantments`].

use std::fmt;
use std::str::FromStr;

use crate::enchanting::Definition;

include!(concat!(env!("OUT_DIR"), "/enchantment.rs"));

/// An enchantment id or name that is not a Bedrock 1.26.51 enchantment.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum UnknownEnchantment {
    #[error("unknown enchantment id {0}")]
    Id(i16),
    #[error("unknown enchantment {0:?}")]
    Name(String),
}

impl Enchantment {
    /// Numeric id, as item NBT stores it.
    pub const fn id(self) -> i16 {
        self as i16
    }

    /// Highest level the enchantment takes.
    pub const fn max_level(self) -> u8 {
        self.definition().max_level
    }

    /// Resource-pack name key (`enchantment.damage.all`).
    pub const fn lang_key(self) -> &'static str {
        self.definition().lang_key
    }
}

impl FromStr for Enchantment {
    type Err = UnknownEnchantment;

    /// Accepts the bare name (`sharpness`, as loot tables write it), the
    /// `minecraft:` identifier and the vanilla aliases (`bow_infinity`).
    /// Any other namespace is rejected.
    fn from_str(name: &str) -> Result<Self, Self::Err> {
        let bare = match name.split_once(':') {
            None => name,
            Some(("minecraft", bare)) => bare,
            Some(_) => return Err(UnknownEnchantment::Name(name.to_owned())),
        };
        Self::from_bare_name(bare).ok_or_else(|| UnknownEnchantment::Name(name.to_owned()))
    }
}

impl TryFrom<String> for Enchantment {
    type Error = UnknownEnchantment;

    fn try_from(name: String) -> Result<Self, Self::Error> {
        name.parse()
    }
}

impl From<Enchantment> for &'static str {
    fn from(enchantment: Enchantment) -> Self {
        enchantment.identifier()
    }
}

impl fmt::Display for Enchantment {
    /// The `minecraft:` identifier.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.identifier())
    }
}

/// The level of every enchantment on one item, indexed by [`Enchantment`]
/// (0 = absent). Item stacks decode it once from their NBT so that queries
/// are an array index.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Enchantments([u8; Enchantment::COUNT]);

impl Default for Enchantments {
    fn default() -> Self {
        Self::NONE
    }
}

impl Enchantments {
    /// No enchantments.
    pub const NONE: Self = Self([0; Enchantment::COUNT]);

    /// Level of `enchantment`, 0 when absent.
    #[inline]
    pub const fn level(&self, enchantment: Enchantment) -> u8 {
        self.0[enchantment as usize]
    }

    /// Set the level of `enchantment` (0 removes it).
    #[inline]
    pub fn set(&mut self, enchantment: Enchantment, level: u8) {
        self.0[enchantment as usize] = level;
    }

    pub fn is_empty(&self) -> bool {
        self.0.iter().all(|level| *level == 0)
    }

    /// The enchantments present, in id order, with their levels.
    pub fn iter(&self) -> impl Iterator<Item = (Enchantment, u8)> + '_ {
        Enchantment::ALL
            .into_iter()
            .zip(self.0)
            .filter(|(_, level)| *level > 0)
    }
}

impl FromIterator<(Enchantment, u8)> for Enchantments {
    /// The first level given for an enchantment wins, as item NBT lookups
    /// take the first matching entry.
    fn from_iter<I: IntoIterator<Item = (Enchantment, u8)>>(levels: I) -> Self {
        let mut seen = [false; Enchantment::COUNT];
        let mut table = Self::NONE;
        for (enchantment, level) in levels {
            if !std::mem::replace(&mut seen[enchantment as usize], true) {
                table.set(enchantment, level);
            }
        }
        table
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SOURCE: &str = include_str!("../../unastar-data/output/available_commands.json");

    /// Every id and name matches the BDS 1.26.51 command capture.
    #[test]
    fn ids_and_names_match_the_bds_capture() {
        let commands: serde_json::Value = serde_json::from_str(SOURCE).unwrap();
        let captured: Vec<&str> = commands["enums"]
            .as_array()
            .unwrap()
            .iter()
            .find(|e| e["name"] == "Enchant")
            .unwrap()["values"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(Enchantment::COUNT, 42);
        assert_eq!(Enchantment::NAMES.as_slice(), captured.as_slice());
        for (id, enchantment) in Enchantment::ALL.into_iter().enumerate() {
            let id = i16::try_from(id).unwrap();
            assert_eq!(enchantment.id(), id);
            assert_eq!(i16::from(enchantment), id);
            assert_eq!(Enchantment::try_from(id), Ok(enchantment));
            assert_eq!(enchantment.name(), captured[id as usize]);
            assert_eq!(
                enchantment.to_string(),
                format!("minecraft:{}", captured[id as usize])
            );
            assert_eq!(enchantment.name().parse(), Ok(enchantment));
            assert_eq!(enchantment.to_string().parse(), Ok(enchantment));
        }
        assert_eq!(Enchantment::Sharpness.id(), 9);
        assert_eq!(Enchantment::Lunge.id(), 41);
    }

    #[test]
    fn unknown_ids_and_names_are_typed_errors() {
        assert_eq!(Enchantment::try_from(42), Err(UnknownEnchantment::Id(42)));
        assert_eq!(Enchantment::try_from(-1), Err(UnknownEnchantment::Id(-1)));
        assert_eq!(
            "speed".parse::<Enchantment>(),
            Err(UnknownEnchantment::Name("speed".into()))
        );
        assert_eq!(
            "foo:sharpness".parse::<Enchantment>(),
            Err(UnknownEnchantment::Name("foo:sharpness".into())),
            "only the minecraft namespace"
        );
        assert!("Sharpness".parse::<Enchantment>().is_err());
    }

    #[test]
    fn vanilla_aliases_parse() {
        assert_eq!("bow_infinity".parse(), Ok(Enchantment::Infinity));
        assert_eq!("minecraft:bow_infinity".parse(), Ok(Enchantment::Infinity));
    }

    #[test]
    fn serde_uses_the_identifier() {
        let json = serde_json::to_value(Enchantment::SilkTouch).unwrap();
        assert_eq!(json, "minecraft:silk_touch");
        let parsed: Enchantment = serde_json::from_value(serde_json::json!("fortune")).unwrap();
        assert_eq!(parsed, Enchantment::Fortune);
        let error = serde_json::from_value::<Enchantment>(serde_json::json!("speed"))
            .unwrap_err()
            .to_string();
        assert!(error.contains("unknown enchantment \"speed\""), "{error}");
    }

    #[test]
    fn rules_come_from_the_data_file() {
        assert_eq!(Enchantment::Sharpness.max_level(), 5);
        assert_eq!(Enchantment::Sharpness.lang_key(), "enchantment.damage.all");
        assert_eq!(Enchantment::Binding.lang_key(), "enchantment.curse.binding");
        assert_eq!(Enchantment::AquaAffinity.max_level(), 1);
        let data: serde_json::Value = serde_json::from_str(include_str!(
            "../../unastar-data/data/measured/enchantments.json"
        ))
        .unwrap();
        for enchantment in Enchantment::ALL {
            let row = &data["enchantments"][enchantment.name()];
            assert_eq!(row["max_level"], enchantment.max_level());
            assert_eq!(row["lang_key"], enchantment.lang_key());
            assert_eq!(row["weight"], enchantment.definition().weight);
        }
    }

    #[test]
    fn level_table_indexes_by_enchantment() {
        let mut table: Enchantments = [
            (Enchantment::Unbreaking, 3),
            (Enchantment::Sharpness, 2),
            (Enchantment::Sharpness, 5),
        ]
        .into_iter()
        .collect();
        assert_eq!(table.level(Enchantment::Sharpness), 2, "first entry wins");
        assert_eq!(table.level(Enchantment::Fortune), 0);
        assert_eq!(
            table.iter().collect::<Vec<_>>(),
            [(Enchantment::Sharpness, 2), (Enchantment::Unbreaking, 3)]
        );
        table.set(Enchantment::Sharpness, 0);
        table.set(Enchantment::Unbreaking, 0);
        assert!(table.is_empty());
        assert_eq!(table, Enchantments::NONE);
    }
}
